(function(){'use strict';
const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),opt=(v,l=v)=>`<option value="${esc(v)}">${esc(l)}</option>`,catalog=window.PRICE_CATALOG,store=window.PriceBook,group=id=>id.replace(/^T\d+_/,'').replace(/_LEVEL[1-4]/,'').replace(/@[1-4]$/,'');
const families=new Map();for(const r of catalog){const key=group(r.id);if(!families.has(key))families.set(key,{key,name:r.name,id:r.id,search:''});families.get(key).search+=(r.name+' '+r.id+' ').toLocaleLowerCase('ru-RU');}
const panel=document.createElement('section');panel.id='prices-content';panel.hidden=true;panel.className='activity-content';document.querySelector('footer').before(panel);
panel.innerHTML=`<section class="panel"><h2>Мои цены</h2><p class="hint">Заполните все тиры и зачарования выбранного предмета. Цены общие для персонажей, отдельно для каждого сервера, города и качества. Личная цена действует до появления проверенного предложения с более поздним временем. Время — время самого ордера, а не загрузки сайта. Отдельные ручные цены внутри партии имеют приоритет.</p><div class="grid2"><label class="field">Поиск по названию или ID<input id="book-search" type="search" placeholder="Например, меч, жаркое, ткань"></label><label class="field">Предмет<select id="book-family"></select></label></div><div class="grid2"><label class="field">Город<select id="book-city">${['Bridgewatch','Fort Sterling','Lymhurst','Martlock','Thetford','Caerleon','Brecilien','Black Market'].map(c=>opt(c,c==='Black Market'?'Карлион · чёрный рынок':c)).join('')}</select></label><label class="field">Качество<select id="book-quality">${[1,2,3,4,5].map((q,i)=>opt(q,['Обычное','Хорошее','Выдающееся','Отличное','Шедевр'][i])).join('')}</select></label></div><p id="book-message" class="hint" role="status"></p><div id="book-table"></div><p class="hint">Закупка — купить предмет по ордеру продажи. Продажа ордером — выставить свой ордер. Мгновенная продажа — цена ордера покупки, включая чёрный рынок. Ручные цены не считаются гарантией оборота. После автоматической замены рыночная цена снова требует свежего подтверждения.</p></section>`;
const market=window.FeatureMarket.create();let active=false,oldServer,family='MAIN_SWORD',city='Lymhurst',quality=1,seq=0;
const view={panel,market,state:{server:'europe'},active:()=>active,activate(){active=true;oldServer=$('server').value;view.state.server=oldServer;$('craft-content').hidden=true;panel.hidden=false;document.querySelectorAll('[data-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mode==='prices'));render();},deactivate(){if(!active)return;active=false;seq++;market.cancel();panel.hidden=true;$('craft-content').hidden=false;$('server').value=oldServer;},render,async refresh(force){if(!active)return;const ticket=++seq,server=view.state.server,rows=current();$('book-message').textContent='Проверяем более поздние предложения…';const message=await market.load(server,rows.map(r=>r.id),force);if(active&&ticket===seq&&server===view.state.server){render();$('book-message').textContent=message||'Проверка завершена. Старые предложения не заменяют ваши цены.';}}};window.ActivityViews.prices=view;
function current(){return catalog.filter(r=>group(r.id)===family).sort((a,b)=>a.tier-b.tier||a.ench-b.ench||a.id.localeCompare(b.id));}
function fill(){const text=$('book-search').value.toLocaleLowerCase('ru-RU');let list=[...families.values()].filter(f=>(f.search+f.key.toLocaleLowerCase('ru-RU')).includes(text)).slice(0,200);if(!list.some(f=>f.key===family)&&families.has(family))list.unshift(families.get(family));$('book-family').innerHTML=list.map(f=>opt(f.key,f.name+' · '+f.key)).join('');$('book-family').value=family;}
function render(){fill();$('book-city').value=city;$('book-quality').value=quality;const focus=document.activeElement,editing=focus?.dataset.bookItem?{id:focus.dataset.bookItem,action:focus.dataset.bookAction,value:focus.value}:null;
 const rows=current();$('book-quality').disabled=!rows.some(r=>r.quality);const columns=[['buy','Закупка'],['sell','Продажа ордером'],['bid','Мгновенная продажа']];
 $('book-table').innerHTML='<div class="table-scroll"><table class="price-book-table"><thead><tr><th>Тир / зачарование</th><th>Предмет</th>'+columns.map(x=>'<th>'+x[1]+'</th>').join('')+'</tr></thead><tbody>'+rows.map(r=>{const q=r.quality?quality:1;return `<tr data-item="${esc(r.id)}"><td>T${r.tier}.${r.ench}</td><td>${esc(r.name)}<small>${esc(r.id)}</small></td>`+columns.map(([action])=>{const result=market.quote(view.state.server,r.id,city,q,action==='bid',action!=='buy'),entry=store?.get(view.state.server,r.id,city,q,action),disabled=city==='Black Market'&&action!=='bid',value=entry?.price??'';return `<td><input type="number" min="0.01" max="1000000000000" step="0.01" data-book-item="${esc(r.id)}" data-book-action="${action}" data-book-quality="${q}" value="${value}" ${disabled||!store?'disabled':''} placeholder="${result.price>0?Math.round(result.price):'Нет цены'}" aria-label="${esc(r.name)} T${r.tier}.${r.ench} ${action}"><small>${entry?esc(new Date(entry.timestamp).toLocaleString('ru-RU'))+' · '+(entry.source==='manual'?'введено вручную':'обновлено рынком'):result.price>0?'Рынок: '+result.price.toLocaleString('ru-RU'):'Не заполнено'}</small></td>`;}).join('')+'</tr>';}).join('')+'</tbody></table></div>';
 if(editing){const input=[...panel.querySelectorAll('[data-book-item]')].find(e=>e.dataset.bookItem===editing.id&&e.dataset.bookAction===editing.action);if(input){input.value=editing.value;input.focus({preventScroll:true});}}
 if(!store)$('book-message').textContent=window.PriceBookError||'Хранилище цен недоступно.';
}
$('book-search').oninput=fill;$('book-family').onchange=()=>{family=$('book-family').value;render();};$('book-city').onchange=()=>{city=$('book-city').value;render();};$('book-quality').onchange=()=>{quality=Number($('book-quality').value);render();};
panel.addEventListener('change',e=>{const el=e.target;if(!el.dataset.bookItem||!store)return;try{const entry=store.set(view.state.server,el.dataset.bookItem,city,Number(el.dataset.bookQuality),el.dataset.bookAction,el.value===''?null:Number(el.value));el.nextElementSibling.textContent=entry?new Date(entry.timestamp).toLocaleString('ru-RU')+' · введено вручную':'Ручная цена удалена';$('book-message').textContent='Цена сохранена. Новее этого времени может быть только время ордера.';document.dispatchEvent(new Event('pricebookchange'));}catch(error){$('book-message').textContent=error.message;}});
view.select=(id)=>{family=group(id);render();};window.PriceBookUI=view;
})();
